$ec_lang['lpn_lock_open_heading']='{name} are acest fișier deschis.';
$ec_lang['lpn_lock_open_readonly']='Deschide doar-citire';
// "Create a copy", not "my own copy" (Tom, 2026-08-04): two projects cannot share one name, and
